code.code:
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "/results.csv"
  },
  "mark": "bar",
  "encoding": {
    "y": {
      "field": "home_score",
      "type":"quantitative",
      "aggregate": "mean"
    },
    "x": {
      "field": "home_team",
      "type": "nominal"
    }
  }
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": "主队与客队平均进球数对比",
  "data": {
    "url": "/results.csv"
  },
  "transform": [
    { "fold": ["home_score", "away_score"], "as": ["team_type", "score"] }
  ],
  "mark": "bar",
  "encoding": {
    "x": {
      "field": "team_type",
      "type": "nominal",
      "title": "队伍类型"  // 主队和客队
    },
    "y": {
      "field": "score",
      "type": "quantitative",
      "aggregate": "mean",
      "title": "平均进球数"
    },
    "color": {
      "field": "team_type",
      "type": "nominal",
      "title": "队伍类型"
    }
  }
}

