{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": "主队与客队平均进球数对比",
  "data": {
    "url": "results.csv",
    "format": {
      "type": "csv",
      "parse": {"home_score": "number", "away_score": "number"}
    }
  },
  "transform": [
    {"fold": ["home_score", "away_score"], "as": ["team_type", "score"]},
    {
      "calculate": "datum.team_type === 'home_score' ? '主队 (Home)' : '客队 (Away)'",
      "as": "队伍"
    }
  ],
  "mark": "bar",
  "encoding": {
    "x": {
      "field": "队伍",
      "type": "nominal",
      "title": "队伍类型",
      "sort": ["主队 (Home)", "客队 (Away)"],
      "axis": {"labelAngle": 0}
    },
    "y": {
      "aggregate": "mean",
      "field": "score",
      "type": "quantitative",
      "title": "平均进球数"
    },
    "color": {
      "field": "队伍",
      "type": "nominal",
      "title": "队伍类型"
    },
    "tooltip": [
      {"field": "队伍", "type": "nominal"},
      {"aggregate": "mean", "field": "score", "type": "quantitative", "title": "平均进球数", "format": ".3f"}
    ]
  }
}

